"""Create an offline viewer of precomputed pixel-decoding observations."""
from pathlib import Path
import json
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parent
result=json.loads((ROOT/'results.json').read_text())
book=json.loads((ROOT/'codebook.json').read_text())
font=ImageFont.truetype(str(ROOT.parents[1]/'brand/fonts/Manrope-Variable.ttf'),20)
board=Image.new('RGB',(1120,860),'#D3EFFF');draw=ImageDraw.Draw(board)
draw.text((32,22),'consta / identidade óptica individual — experimento sintético',fill='#154F6F',font=font)
for i,tag in enumerate(book['tags'][:12]):
 x=28+(i%4)*274;y=80+(i//4)*240
 marker=Image.open(ROOT/f'tags/{tag["tag_id"]}.png').convert('RGB');marker.thumbnail((195,195))
 board.paste(marker,(x+28,y));draw.text((x+38,y+202),tag['tag_id'],fill='#154F6F',font=font)
draw.text((32,830),'Mesma estrutura. Identidades distintas. Leitura não é garantia universal.',fill='#154F6F',font=font)
board.save(ROOT/'overview.png')
html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Consta — emulação óptica</title><style>@font-face{font-family:Manrope;src:url('../../brand/fonts/Manrope-Variable.ttf')}*{box-sizing:border-box}body{font-family:Manrope,system-ui,sans-serif;margin:0;color:#154F6F;background:#f5f7f8}header{background:#154F6F;color:white;padding:40px max(24px,6vw)}header small{color:#D3EFFF}header h1{font-size:clamp(25px,4vw,44px);max-width:900px}header p{max-width:820px;line-height:1.7}main{padding:32px max(24px,6vw);max-width:1500px;margin:auto}label{display:inline-grid;gap:8px;margin:0 20px 25px 0}select{font:inherit;padding:12px;background:white;border:1px solid #bbcbd5;border-radius:8px;color:inherit}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}.card{background:white;border-radius:18px;padding:24px;border:1px solid #e0e8ec}.card img{width:100%;max-width:300px;display:block;margin:auto;image-rendering:auto}.result{font-size:25px;font-weight:700;margin:25px 0 12px}.note{line-height:1.7;max-width:1000px}.badge{padding:6px 12px;border-radius:30px;background:#D3EFFF;display:inline-block;font-size:13px}table{border-collapse:collapse;width:100%;background:white;font-size:14px}td,th{padding:12px;border-bottom:1px solid #d9e3e9;text-align:left}.tags{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px}.tags a{background:white;padding:10px;text-align:center;border-radius:8px;font-size:11px;color:inherit}.tags img{width:100%}h2{margin-top:40px}a{color:inherit}footer{padding:35px;line-height:1.7}#multi{width:100%;max-width:800px}.warn{background:#fff1db;border-left:4px solid #a66c15;padding:16px;border-radius:8px}</style><header><small>CONSTA / PESQUISA AUTORAL / SPIKE DESCARTÁVEL</small><h1>Mesmo desenho geral.<br>Cada equipamento tem sua identidade.</h1><p>Tags circulares com padrões internos diferentes, detectadas automaticamente a partir dos pixels. Este explorador mostra resultados pré-calculados da emulação; não usa câmera real e não comprova alcance, cobertura hospitalar ou compatibilidade clínica.</p></header><main><label>Identidade de referência<select id="tag"></select></label><label>Condição sintética<select id="scenario"></select></label><div class="cards"><section class="card"><span class="badge">Etiqueta original</span><img id="source" alt="Tag de referência"><p id="identity"></p></section><section class="card"><span class="badge">Imagem recebida pelo detector</span><img id="camera" alt="Imagem sintética degradada"><p id="condition"></p></section><section class="card"><span class="badge">Saída do algoritmo</span><div id="decoded" class="result"></div><p id="explanation" class="note"></p><p class="note">O ID esperado é usado somente na avaliação. O detector encontra contornos e lê setores da imagem, sem receber posição, transformação ou ID verdadeiro do renderizador.</p></section></div><h2>Resultados por condição</h2><p class="note">Contagens da família testada. Rejeição significa ausência de ID aceito; não identifica, por si, a causa física da falha. Ausência de trocas nesta bateria finita não prova probabilidade zero em outros cenários.</p><table><thead><tr><th>Condição</th><th>ID correto</th><th>Sem ID aceito</th><th>ID incorreto / extra</th></tr></thead><tbody id="summary"></tbody></table><h2>Vários equipamentos na mesma imagem</h2><img id="multi" src="assets/multiple.png" alt="Cena com múltiplas tags"><p id="multiResults"></p><h2>Movimentação entre ambientes fictícios</h2><p class="note">Replay de quadros decodificados a partir dos pixels. Os rótulos vêm das observações; a cobertura de uma marca interrompe sua identificação.</p><img style="width:100%;max-width:900px" src="replay.gif" alt="Replay sintético com tags em movimento e perda de visibilidade"><h2>Dicionário de etiquetas</h2><p class="note">Família finita de identidades. Clique para abrir a imagem. São arquivos de demonstração, não etiquetas aprovadas para impressão e uso clínico.</p><div id="tags" class="tags"></div><h2>Limites que importam</h2><div class="note warn">O detector usa aproximação por elipse: perspectiva projetiva forte não é resolvida. Marca totalmente coberta não é observável. Não há escala física em metros, material MR avaliado, câmera real, tráfego BLE ou ensaio de interferência. A identidade visual pode ser copiada ou trocada de equipamento; ela não é autenticação criptográfica.</div><footer><a href="README.md">Método e reprodução</a> · <a href="results.json">Observações completas</a> · <a href="codebook.json">Dicionário</a> · <a href="verification.json">Sequência sintética adicional</a></footer></main><script>const DATA=__RESULTS__;const BOOK=__BOOK__;const names={clean:'Sem degradação',rotation:'Rotação',blur:'Desfoque',low_light:'Baixa iluminação',small:'Redução da imagem',tiny:'Resolução extrema',oblique:'Inclinação afim',perspective:'Perspectiva forte',partial_cover:'Cobertura parcial',covered:'Cobertura total',mirror:'Espelhamento',unknown:'Padrão fora do dicionário',empty:'Cena vazia'};const tag=document.querySelector('#tag'),scenario=document.querySelector('#scenario');BOOK.tags.slice(0,8).forEach(t=>tag.add(new Option(t.tag_id,t.tag_id)));Object.keys(names).filter(s=>!['unknown','empty'].includes(s)).forEach(s=>scenario.add(new Option(names[s],s)));function update(){const id=tag.value,s=scenario.value,row=DATA.observations.find(r=>r.expected===id&&r.scenario===s);document.querySelector('#source').src='tags/'+id+'.png';document.querySelector('#camera').src='assets/'+id+'-'+s+'.png';document.querySelector('#identity').textContent='Referência da avaliação: '+id;document.querySelector('#condition').textContent=names[s];document.querySelector('#decoded').textContent=row.detected.length?row.detected.join(', '):'Nenhum ID aceito';document.querySelector('#explanation').textContent=row.status==='correct'?'O ID lido dos pixels corresponde à referência neste quadro sintético.':row.status==='rejected'?'O detector não aceitou uma identidade. A demonstração não preenche a lacuna com o ID esperado.':'A saída não corresponde à referência. Esta é uma falha que deve permanecer visível.'}tag.onchange=scenario.onchange=update;update();for(const[s,c]of Object.entries(DATA.scenario_counts)){const tr=document.createElement('tr');for(const v of[names[s],c.correct,c.rejected,c.wrong]){const td=document.createElement('td');td.textContent=v;tr.append(td)}document.querySelector('#summary').append(tr)}for(const t of BOOK.tags){const a=document.createElement('a');a.href='tags/'+t.tag_id+'.png';const im=document.createElement('img');im.src=a.href;im.alt=t.tag_id;a.append(im,document.createTextNode(t.tag_id));document.querySelector('#tags').append(a)}document.querySelector('#multiResults').textContent='IDs aceitos pelo detector: '+DATA.multiple_scene_detections.map(d=>d.tag_id).join(', ');</script></html>'''
(ROOT/'index.html').write_text(html.replace('__RESULTS__',json.dumps(result)).replace('__BOOK__',json.dumps(book)))
print('Offline gallery and overview built.')
